(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;else root.OCModel=api;})(globalThis,()=>{
  const templates={world:['环境与地理','生物与生态','历史与时代','社会与文化','力量体系','规则与禁忌'],character:['性别与代词','年龄与种族','生平与经历','性格与动机','外貌与轮廓','服装与配饰','配色与材质','标志性细节','能力与限制','人际关系'],event:['时间与地点','参与角色','起因','事件经过','影响与后果']};
  const kinds={world:'世界观',character:'角色',event:'特别事件'},statuses={confirmed:'已确定',tentative:'讨论中',open:'待补充'};
  function error(message,status=400){const e=new Error(message);e.status=status;throw e;}
  function text(value,max=12000){if(typeof value!=='string'||value.length>max)error('文本格式不正确或超出长度限制');return value.trim();}
  const id=()=>crypto.randomUUID();
  function entity(kind,name){if(!Object.hasOwn(templates,kind))error('未知档案类型');return {id:id(),kind,name:text(name,160),summary:'',image:'',links:[],fields:templates[kind].map(label=>({id:id(),label,value:'',status:'open',evidence:'',source:'',updatedAt:new Date().toISOString()}))};}
  function create(input){const name=text(input.title||'未命名设计',160);if(!name)error('请填写项目名称');const now=new Date().toISOString();return {id:id(),title:name,summary:text(input.summary||'',3000),category:text(input.category||'未分类',80),tags:[],stage:'draft',revision:1,createdAt:now,updatedAt:now,entities:[entity('world','世界观概况')],history:[],versions:[],requests:[]};}
  function stats(project){const fields=project.entities.flatMap(e=>e.fields);const confirmed=fields.filter(f=>f.status==='confirmed'&&f.value).length;return {fields:fields.length,confirmed,tentative:fields.filter(f=>f.status==='tentative').length,open:fields.filter(f=>f.status==='open'||!f.value).length,percent:fields.length?Math.round(confirmed/fields.length*100):0,characters:project.entities.filter(e=>e.kind==='character').length,events:project.entities.filter(e=>e.kind==='event').length};}
  function safeImage(value){value=text(value,2800000);if(!value)return '';if(/^data:image\/(png|jpeg|webp|gif);base64,[a-z0-9+/=]+$/i.test(value))return value;try{const u=new URL(value);if(['http:','https:'].includes(u.protocol)&&!u.username&&!u.password)return u.href;}catch{}error('参考图需要 HTTP(S) 地址或 PNG/JPEG/WebP/GIF 图片');}
  function apply(original,input,actor='user'){if(!input||!Number.isInteger(input.expectedRevision))error('请提供 expectedRevision 以避免覆盖其他会话的修改');if(input.requestId&&original.requests?.includes(input.requestId))return {project:structuredClone(original),replayed:true};if(input.expectedRevision!==original.revision)error('档案已被其他会话修改，请重新读取后更新',409);if(original.stage==='archived'&&(input.operations||[]).some(o=>o.op!=='restore'))error('已归档项目只读，请先恢复设计',409);if(!Array.isArray(input.operations)||!input.operations.length||input.operations.length>100)error('每批需要1至100条修改');const p=structuredClone(original),now=new Date().toISOString(),changes=[];for(const op of input.operations){if(!op||typeof op!=='object')error('修改格式不正确');let e,f;const find=()=>{e=p.entities.find(x=>x.id===op.entityId);if(!e)error('没有找到指定档案');return e;};switch(op.op){
    case 'project.update': for(const key of ['title','summary','category'])if(op[key]!==undefined)p[key]=text(op[key],key==='summary'?3000:160);if(!p.title)error('项目名称不能为空');if(op.tags!==undefined){if(!Array.isArray(op.tags)||op.tags.length>20)error('标签格式不正确');p.tags=op.tags.map(v=>text(v,40));}changes.push('更新项目概况');break;
    case 'entity.add': e=entity(op.kind,op.name);if(!e.name)error('档案名称不能为空');if(p.entities.length>=200)error('单项目最多200份档案');p.entities.push(e);changes.push(`新增${kinds[e.kind]}：${e.name}`);break;
    case 'entity.update':find();if(op.name!==undefined)e.name=text(op.name,160);if(!e.name)error('档案名称不能为空');if(op.summary!==undefined)e.summary=text(op.summary,4000);if(op.image!==undefined)e.image=safeImage(op.image);if(op.links!==undefined){if(!Array.isArray(op.links)||op.links.some(v=>!p.entities.some(x=>x.id===v)))error('关联档案不存在');e.links=[...new Set(op.links)].filter(v=>v!==e.id);}changes.push(`更新档案：${e.name}`);break;
    case 'field.set':find();f=e.fields.find(x=>x.id===op.fieldId);if(!f)error('没有找到指定设定');if(op.value!==undefined)f.value=text(op.value);if(op.status!==undefined){if(!Object.hasOwn(statuses,op.status))error('未知确定状态');f.status=op.status;}if(op.evidence!==undefined)f.evidence=text(op.evidence,3000);if(op.source!==undefined)f.source=text(op.source,2000);if(!f.value&&f.status==='confirmed')error('空白设定不能标记为已确定');if(actor==='agent'&&f.status==='confirmed'&&(!op.evidence?.trim()||!op.source?.trim()))error('AI确认设定时必须附上用户确认原话与讨论来源');f.updatedAt=now;changes.push(`${e.name} / ${f.label}：${statuses[f.status]}`);break;
    case 'field.add':find();if(e.fields.length>=100)error('单档案最多100条设定');const label=text(op.label,120);if(!label)error('设定名称不能为空');e.fields.push({id:id(),label,value:'',status:'open',evidence:'',source:'',updatedAt:now});changes.push(`新增设定：${e.name} / ${label}`);break;
    case 'snapshot':if(p.versions.length>=100)error('已达到100个保存版本，请导出备份后整理项目');p.versions.push({id:id(),name:text(op.name||'设计快照',160),createdAt:now,revision:original.revision,document:document(p)});changes.push('保存设计版本');break;
    case 'archive':if(p.versions.length>=100)error('已达到100个保存版本，请导出备份后整理项目');p.versions.push({id:id(),name:text(op.name||'归档定稿',160),createdAt:now,revision:original.revision,document:document(p)});p.stage='archived';changes.push('归档设计');break;
    case 'restore':p.stage='draft';changes.push('恢复设计');break;
    default:error('不支持的操作：'+op.op);
  }}p.revision++;p.updatedAt=now;p.history.unshift({id:id(),at:now,actor,source:text(input.source||'',2000),note:text(input.note||changes.join('；'),3000),changes});p.history=p.history.slice(0,500);if(input.requestId){p.requests.push(text(input.requestId,160));p.requests=p.requests.slice(-200);}return {project:p,replayed:false};}
  function document(p){const {history,versions,requests,...rest}=structuredClone(p);return rest;}
  function validateImport(value){if(!value||value.format!=='william-oc-archive'||value.version!==1||!value.project)error('不支持的档案备份格式');const p=value.project;if(typeof p.title!=='string'||!Array.isArray(p.entities)||p.entities.length>200)error('档案结构不正确');const fresh=create({title:p.title,summary:p.summary||'',category:p.category||'未分类'});fresh.tags=Array.isArray(p.tags)?p.tags.slice(0,20).map(t=>text(t,40)):[];fresh.entities=[];const seen=new Set();for(const raw of p.entities){if(!Object.hasOwn(templates,raw.kind)||!Array.isArray(raw.fields)||raw.fields.length>100)error('档案类型或设定无效');const e=entity(raw.kind,raw.name);e.id=typeof raw.id==='string'&&raw.id.length<100?raw.id:id();if(seen.has(e.id))error('档案标识重复');seen.add(e.id);e.summary=text(raw.summary||'',4000);e.image=safeImage(raw.image||'');e.links=Array.isArray(raw.links)?raw.links.filter(v=>typeof v==='string'):[];e.fields=raw.fields.map(f=>{if(!Object.hasOwn(statuses,f.status))error('未知状态');return {id:id(),label:text(f.label,120),value:text(f.value||''),status:f.value?f.status:'open',evidence:text(f.evidence||'',3000),source:text(f.source||'',2000),updatedAt:fresh.createdAt};});fresh.entities.push(e);}for(const e of fresh.entities)e.links=e.links.filter(v=>seen.has(v)&&v!==e.id);return fresh;}
  return {templates,kinds,statuses,create,entity,stats,apply,document,validateImport,error};
});
